<?php
/**
 * 拼音首字母映射表（取每个字拼音的首字母）
 * 覆盖 20902 个汉字
 * 零声母字（如"案"àn）会取到"a"，不再是空值
 * zh/ch/sh → z/c/s 已简化
 */
function generatePinyinInitials($name) {
    static $map = null;
    if ($map === null) {
        $map = [];
        $data = base64_decode('');
        $pairs = explode(',', $data);
        foreach ($pairs as $pair) {
            if ($pair === '') continue;
            $parts = explode(':', $pair);
            $map[(int)$parts[0]] = $parts[1];
        }
    }

    $len = mb_strlen($name);
    $result = '';
    for ($i = 0; $i < $len; $i++) {
        $ch = mb_substr($name, $i, 1);
        $code = mb_ord($ch);
        $result .= $map[$code] ?? '';
    }
    return $result;
}
